-- Frozen cf638ec v1 subject triggers; compatibility evidence, not a second writer.
CREATE TRIGGER "cw_meter_meter_fixture_delete" AFTER DELETE ON "meter_fixture" BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM market_counts WHERE category='direct_shared' AND records>=0 AND logical_bytes>=0) THEN RAISE(ABORT,'Missing subject storage counter') END;UPDATE market_counts SET records=records-1,logical_bytes=logical_bytes-(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END),deleted_bytes=deleted_bytes+(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END) WHERE category='direct_shared'; END;
CREATE TRIGGER "cw_meter_meter_fixture_insert" AFTER INSERT ON "meter_fixture" BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM market_counts WHERE category='direct_shared' AND records>=0 AND logical_bytes>=0) THEN RAISE(ABORT,'Missing subject storage counter') END;UPDATE market_counts SET records=records+1,logical_bytes=logical_bytes+(CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END),inserted_bytes=inserted_bytes+(CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END) WHERE category='direct_shared'; END;
CREATE TRIGGER "cw_meter_meter_fixture_update" AFTER UPDATE ON "meter_fixture" WHEN (CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END)<>(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM market_counts WHERE category='direct_shared' AND records>=0 AND logical_bytes>=0) THEN RAISE(ABORT,'Missing subject storage counter') END;UPDATE market_counts SET logical_bytes=logical_bytes+(CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END)-(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END),inserted_bytes=inserted_bytes+max(0,(CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END)-(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END)),deleted_bytes=deleted_bytes+max(0,(CASE typeof(OLD."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."id" AS BLOB)) END+CASE typeof(OLD."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."payload" AS BLOB)) END+CASE typeof(OLD."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(OLD."refs" AS BLOB)) END)-(CASE typeof(NEW."id") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."id" AS BLOB)) END+CASE typeof(NEW."payload") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."payload" AS BLOB)) END+CASE typeof(NEW."refs") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST(NEW."refs" AS BLOB)) END)) WHERE category='direct_shared'; END;
